// Revisión diaria solo durante la primera semana (hasta el domingo 5 de octubre de 2026 incluido)
const hasta = new Date('2026-10-05T23:59:59+02:00');
if (new Date() > hasta && !$('Ejecutar ahora (manual)').isExecuted) return [];
return [{ json: { inicio: new Date().toISOString() } }];

// Dos búsquedas por banco (marcas de tiempo exactas, misma ventana de 2 días que la búsqueda de los bancos):
//  fuga         = correo del banco sin recoger (sin n8n-visto) con más de 1 h → no debería existir
//  sin_procesado = recogido hace más de 2 h pero sin etiqueta Procesado → revisar
const now = Math.floor(Date.now() / 1000);
const banks = $('Bancos a vigilar').all().map(i => i.json);
const out = [];
for (const b of banks) {
  out.push({ json: { bank: b.name, tipo: 'fuga', q: `${b.base} -label:n8n-visto after:${now - 47 * 3600} before:${now - 3600}` } });
  out.push({ json: { bank: b.name, tipo: 'sin_procesado', q: `${b.base} label:n8n-visto after:${now - 72 * 3600} before:${now - 7200}` } });
}
return out;

// Junta todos los datos y calcula los hallazgos de forma determinista (la IA solo redacta)
const now = Date.now();
const banks = $('Bancos a vigilar').all().map(i => i.json);
const last = $('Última ejecución').all().map(i => (i.json.data || [])[0] || null);
const wfs = ($('Estado workflows').first().json.data || []);
const wfById = Object.fromEntries(wfs.map(w => [w.id, w]));
const OTHER = {"OjNQDNcBsDOj78gS": "OFFERS · Repartidor de correos bancarios", "Vrvs44IG0BaKPLlH": "Santander - Daily Status Sync", "SVMlT6a9uSRlZjHU": "SANTANDER OFFER", "dVozY20frxVJmNXw": "Kutxabank ZIP Creator", "P3uI8Ejm8qQbHWSg": "Kutxabank Email Sender", "fIZemWSyjTjiM8cn": "Kutxabank Rastreator Sync", "HmdIF5DLPIOJiGas": "Kutxabank Daily Email", "p9WkjPl75vFBvrAW": "Ibercaja - Send Dossier", "uQpf3C5LaecqDvoF": "Ibercaja · Excel datos básicos", "awyhc675ipFuqqXv": "OFFERS · Registrar respuesta", "3dRzXNAhcsj7vsaV": "OFFERS · Error handler"};
const findings = [];

// 1) Repartidor de correos al día (busca los correos de los 18 bancos cada 5 min) y bancos activos
const rep = ($('Repartidor: última ejecución').first().json.data || [])[0];
const repMin = rep ? Math.round((now - Date.parse(rep.startedAt)) / 60000) : null;
if (!wfById['OjNQDNcBsDOj78gS']?.active) findings.push('Repartidor de correos bancarios: DESACTIVADO (no se recoge ningún correo)');
else if (repMin === null || repMin > 20) findings.push(`Repartidor de correos bancarios: no se ejecuta desde hace ${repMin ?? '?'} min`);
else if (rep.status === 'error') findings.push('Repartidor de correos bancarios: su última ejecución falló');
const polling = banks.map((b, i) => {
  const e = last[i]; const w = wfById[b.id];
  if (!w?.active) findings.push(`${b.name}: workflow DESACTIVADO`);
  return { banco: b.name, activo: !!w?.active, ultimo_correo_procesado: e?.startedAt || null, estado_ultimo: e?.status || null };
});
for (const [id, name] of Object.entries(OTHER)) {
  const w = wfById[id];
  if (w && !w.active && !['SANTANDER OFFER','Ibercaja · Excel datos básicos','OFFERS · Registrar respuesta','OFFERS · Error handler'].includes(name)) findings.push(`${name}: workflow DESACTIVADO`);
}

// 2) Errores de las últimas 24 h
const WATCH = new Set([...banks.map(b => b.id), ...Object.keys(OTHER)]);
const errs = ($('Errores recientes').first().json.data || [])
  .filter(e => WATCH.has(e.workflowId) && now - Date.parse(e.startedAt) < 24 * 3600e3)
  // errores anteriores a la última modificación del workflow se consideran ya corregidos
  .filter(e => !wfById[e.workflowId]?.updatedAt || Date.parse(e.startedAt) > Date.parse(wfById[e.workflowId].updatedAt))
  .map(e => ({ workflow: wfById[e.workflowId]?.name || e.workflowId, cuando: e.startedAt, nodo: e.data?.resultData?.lastNodeExecuted || null,
               error: String(e.data?.resultData?.error?.message || '').slice(0, 160), url: `https://huspy.app.n8n.cloud/workflow/${e.workflowId}/executions/${e.id}` }));
const errByWf = {};
for (const e of errs) errByWf[e.workflow] = (errByWf[e.workflow] || 0) + 1;
for (const [wfn, n] of Object.entries(errByWf)) findings.push(`${wfn}: ${n} ejecución(es) con error en 24 h`);

// 3) Gmail: fugas y correos recogidos sin etiqueta Procesado
const qs = $('Consultas Gmail').all().map(i => i.json);
const res = $('Gmail buscar').all().map(i => i.json);
// Correos sin etiqueta "Procesado": las ramas de error no etiquetan a propósito, pero si el correo ya está
// resuelto/procesado en el Command Center no hay nada que revisar → solo cuentan los no registrados o abiertos.
const msgStatus = ($('Command Center: datos').first().json || {}).message_status || {};
const HANDLED = new Set(['resolved', 'processed']);
const gmail = qs.map((q, i) => {
  const ids = (res[i]?.messages || []).map(m => m.id);
  const pend = q.tipo === 'sin_procesado' ? ids.filter(id => !HANDLED.has(msgStatus[id])) : ids;
  return { ...q, n: pend.length, total: ids.length, sin_registro: pend.filter(id => !msgStatus[id]).length, ids: pend.slice(0, 10), error: res[i]?.error?.message || null };
});
for (const g of gmail) {
  if (g.error) findings.push(`${g.bank}: no se pudo consultar Gmail (${g.error})`);
  else if (g.tipo === 'fuga' && g.n > 0) findings.push(`${g.bank}: ${g.n} correo(s) del banco SIN RECOGER con más de 1 h (posible fuga)`);
  else if (g.tipo === 'sin_procesado' && g.n > 0) findings.push(`${g.bank}: ${g.n} correo(s) recogidos sin etiqueta Procesado y sin resolver en el Command Center (${g.sin_registro} sin registrar) — ids: ${g.ids.join(', ')}`);
}

// 4) Command Center
const cc = $('Command Center: datos').first().json || {};
const login = $('Command Center: disponible').first().json || {};
if (!(login.statusCode >= 200 && login.statusCode < 400)) findings.push(`Command Center: /login responde ${login.statusCode ?? 'sin respuesta'}`);
if (cc.error) findings.push(`Command Center: /api/health/offers falló (${cc.error})`);
const att = cc.responses?.attention_open || [];
if (att.length) findings.push(`Ofertas recibidas: ${att.length} respuesta(s) en «Requieren atención»`);
const mis = cc.misplaced_bank_deals_in_opportunity || [];
for (const d of mis) findings.push(`Pipedrive: deal bancario en pipeline Opportunity → ${d.title} (https://mdsl.pipedrive.com/deal/${d.id})`);
const kx = cc.kutxabank?.approved_with_missing_docs || [];   // estado normal: va al resumen, no es hallazgo

const r24 = cc.responses?.last24h_by_bank || [];
const tot = (k) => r24.reduce((n, r) => n + Number(r[k] || 0), 0);
return [{ json: {
  fecha: new Date().toLocaleDateString('es-ES', { timeZone: 'Europe/Madrid', weekday: 'long', day: 'numeric', month: 'long' }),
  hallazgos: findings,
  resumen: { repartidor_ultima_ejecucion_min: repMin, respuestas_24h: tot('total'), ofertas_24h: tot('offers'), rechazos_24h: tot('rejections'), mas_info_24h: tot('more_info'),
             atencion_abierta: att.length, envios_plataforma_pendientes: cc.platform?.pending_dispatches ?? null,
             kutxabank_aprobados: cc.kutxabank?.approved ?? null, kutxabank_con_docs_faltantes: kx.length, errores_24h: errs.length, bancos_vigilados: banks.length },
  detalle: { polling, errores: errs.slice(0, 15), gmail: gmail.filter(g => g.n > 0 || g.error), atencion: att.slice(0, 10), mal_ubicados: mis, kutxabank_faltantes: kx },
} }];

