// Mensaje final: título + informe de la IA + mención a Juanjo solo si hay algo que corregir
const d = $('Consolidar').first().json;
const ia = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n').trim();   // ignora bloques de razonamiento
const hay = d.hallazgos.length > 0;
const cuerpo = ia || (hay ? d.hallazgos.map(h => '• ' + h).join('\n') : 'Todo correcto.');
const titulo = hay
  ? `:rotating_light: *Revisión diaria de flujos bancarios* — ${d.fecha} · *${d.hallazgos.length} punto(s) a revisar* <@U0A6ZSLGC1Y>`
  : `:white_check_mark: *Revisión diaria de flujos bancarios* — ${d.fecha} · sin incidencias`;
return [{ json: { text: `${titulo}\n\n${cuerpo}\n\n_Revisión automática (n8n + Claude) · activa hasta el 5 de octubre._` } }];
